      "codigo_refatorado": "using System;\\nusing System.Collections.Generic;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n        public GameObject testPrefab;\\n\\n        [Range(1, 20)]\\n        public float spawnRadius = 10f;\\n        [Range(1, 50)]\\n        public int cubesPerFrame = 1;\\n        public bool useUniqueMaterials = false;\\n        [Range(1, 512)]\\n        public int cpuScansPerFrame = 1;\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n        [Range(0, 2000)]\\n        public int prepopulateCount = 0;\\n\\n        private StringBuilder _cachedStringBuilder;\\n        private MaterialPropertyBlock _propBlock;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\"_Color\");\\n        private readonly List<GameObject> _spawnedObjects = new List<GameObject>();\\n\\n        private void Awake()\\n        {\\n            _cachedStringBuilder = new StringBuilder(gcConcatIterations * 4);\\n            _propBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                new GameObject(\"Empty_\" + i);\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                var col = quad.GetComponent<Collider>();\\n                if (col != null) Destroy(col);\\n                quad.name = \"Overdraw_\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _cachedStringBuilder.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _cachedStringBuilder.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                // Evita GameObject.FindObjectsOfType a cada frame. Usa a lista rastreada.\\n                int count = _spawnedObjects.Count;\\n                for (int k = 0; k < cpuScansPerFrame; k++)\\n                {\\n                    for (int i = 0; i < count; i++)\\n                    {\\n                        var obj = _spawnedObjects[i];\\n                        if (obj != null)\\n                        {\\n                            obj.transform.position += Vector3.zero;\\n                        }\\n                    }\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(\\n                testPrefab,\\n                UnityEngine.Random.insideUnitSphere * spawnRadius,\\n                Quaternion.identity);\\n\\n            _spawnedObjects.Add(clone);\\n\\n            if (useUniqueMaterials)\\n            {\\n                var rend = clone.GetComponent<Renderer>();\\n                if (rend != null)\\n                {\\n                    rend.GetPropertyBlock(_propBlock);\\n                    _propBlock.SetColor(ColorPropertyId, new Color(\\n                        UnityEngine.Random.value,\\n                        UnityEngine.Random.value,\\n                        UnityEngine.Random.value));\\n                    rend.SetPropertyBlock(_propBlock);\\n                }\\n            }\\n        }\\n    }\\n}\",\\n      \"explicacao_didatica\": \"Toda vez que juntamos textos usando o operador '+' ou instanciamos 'new' dentro do Update, o Unity reserva um novo espaço na memória do computador. O problema é que esses pedaços de memória são descartados logo em seguida, virando 'lixo'. Quando acumula muito lixo, o Garbage Collector (o coletor de lixo da memória) precisa congelar o jogo para limpar tudo, o que causa travamentos visíveis (stutters). Trocamos o operador '+' por um 'StringBuilder' reaproveitado e eliminamos alocações desnecessárias a cada frame.\"\\n    },\\n    {\\n      \"tipo\": \"CPU\",\\n      \"causa_raiz\": \"Chamada massiva de 'GameObject.FindObjectsOfType<GameObject>()' repetida 'cpuScansPerFrame' vezes dentro do método Update(). O método FindObjectsOfType varre a hierarquia inteira da cena de forma custosa e aloca um array novo a cada execução, consumindo até 136.10 ms de tempo de processamento de CPU por frame.\",\\n      \"codigo_refatorado\": \"// Trecho refatorado contido na classe principal:\\n// Em vez de varrer a cena com GameObject.FindObjectsOfType<GameObject>(),\\n// mantemos e iteramos sobre uma coleção interna pré-existente (_spawnedObjects),\\n// reduzindo o custo de busca global de O(N) para acesso direto em memória cacheada.\",\\n      \"explicacao_didatica\": \"O método 'FindObjectsOfType' é como procurar uma pessoa gritando em uma cidade inteira de porta em porta toda vez que o relógio bate um segundo. Em vez de pedir para o computador olhar todos os objetos existentes na cena repetidamente a cada fração de segundo, nós simplesmente guardamos em uma lista apenas os objetos que criamos e consultamos essa lista diretamente, economizando tempo precioso do processador.\"\\n    }\\n  ],\\n  \"dicas_level_design\": null\\n}"
  ,"explicacao_didatica": "Refatoração aplicada para eliminar alocações e buscas custosas por frame."
